+/// Return the longest resolved import path from `entry_uri`, measured in
+/// edges. DomainForge emits this graph only after it has resolved relative,
+/// namespace, and std imports and rejected cycles, but the traversal still
+/// fails closed if an inconsistent cycle ever reaches this boundary.
+fn max_import_depth(entry_uri: &str, edges: &[CanonicalImportEdge]) -> Result<usize, ForgeError> {
+    let mut children: BTreeMap<String, Vec<String>> = BTreeMap::new();
+    for edge in edges {
+        children
+            .entry(edge.importer.clone())
+            .or_default()
+            .push(edge.imported.clone());
+    }
+
+    fn visit(
+        module: &str,
+        children: &BTreeMap<String, Vec<String>>,
+        depths: &mut BTreeMap<String, usize>,
+        visiting: &mut BTreeSet<String>,
+    ) -> Result<usize, ForgeError> {
+        if let Some(depth) = depths.get(module) {
+            return Ok(*depth);
+        }
+        if !visiting.insert(module.to_owned()) {
+            return Err(domain_model_error(format!(
+                "resolved import graph contains cycle at {module}"
+            )));
+        }
+
+        let mut depth = 0;
+        if let Some(imports) = children.get(module) {
+            for imported in imports {
+                depth = depth.max(visit(imported, children, depths, visiting)? + 1);
+            }
+        }
+        visiting.remove(module);
+        depths.insert(module.to_owned(), depth);
+        Ok(depth)
+    }
+
+    visit(
+        entry_uri,
+        &children,
+        &mut BTreeMap::new(),
+        &mut BTreeSet::new(),
+    )
